import*as THREE from'three';import{materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{roundedRect,capsule}from'../../core/geometry.js';
export{THREE,mesh,FACE,portQuaternion,roundedRect,capsule};export const tau=Math.PI*2,plastic=(c=0x222622)=>materials.plastic(c,{roughness:.79}),metal=(c=0xb4b8b0)=>materials.metal(c,{roughness:.42});export const box=(p,s,at,m,n)=>mesh(p,new THREE.BoxGeometry(...s),m,at,n);export const solid=(p,s,d,at,m,n)=>mesh(p,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:40}),m,at,n);export const hole=(s,x,y,r)=>{const h=new THREE.Path();h.absarc(x,y,r,0,tau,false);s.holes.push(h);return h;};export function annulus(p,ro,ri,d,at,m,n){const s=new THREE.Shape();s.absarc(0,0,ro,0,tau,false);hole(s,0,0,ri);return solid(p,s,d,at,m,n);}export function frame(p,name,at=[0,0,0],face=null){const g=new THREE.Group();g.name=name;g.position.fromArray(at);if(face)g.quaternion.copy(FACE[face]);p.add(g);return g;}export function wire(p,a,b,r,m,n){const av=new THREE.Vector3(...a),bv=new THREE.Vector3(...b),v=bv.clone().sub(av),o=mesh(p,new THREE.CylinderGeometry(r,r,v.length(),16),m,av.add(bv).multiplyScalar(.5).toArray(),n);o.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),v.normalize());return o;}
